import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            key = f\"{name} [{fw['framework']}]\"
            pkgs = {}
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg.get('resolvedVersion', '')
            result[key] = pkgs
    return result

before = extract(b)
after = extract(a)

print('=== CHANGES ===')
changes = False
for key in sorted(set(list(before.keys()) + list(after.keys()))):
    bp = before.get(key, {})
    ap = after.get(key, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, 'MISSING')
        av = ap.get(pkg, 'MISSING')
        if bv != av:
            print(f'  {key}: {pkg} {bv} -> {av}')
            changes = True
if not changes:
    print('  (none - version neutral)')

print()
print('=== UNCHANGED ===')
count = 0
for key in sorted(before.keys()):
    bp = before.get(key, {})
    ap = after.get(key, {})
    for pkg in sorted(bp.keys()):
        if bp[pkg] == ap.get(pkg):
            count += 1
print(f'  {count} package references unchanged')
"

